let bars = [];
let clrs = [];
let numMove;
let tileS;

function setup() {
	const minWH = max(windowWidth, windowHeight)
	createCanvas(windowWidth, windowHeight); // (minWH, minWH);
	background(0)
	pixelDensity(1);
	frameRate(30);

	// clrs = ["white", "cyan", "blue", "purple", "red", "orange", "yellow"];
	// https://www.color-hex.com/color-palette/61235
	clrs = ["#711c91", "#ea00d9", "#0abdc6", "#133e7c"];

	// const minWH = max(width, height);
	tileS = minWH * 1 / 6;

	bars = [];
	for (let y = (height - minWH + tileS) * 0.5; y <= height; y += tileS) {
		for (let x = (width - minWH + tileS) * 0.5; x <= width; x += tileS) {
			// bars.push(new NeonBar(x, y, random(TWO_PI), tileS, random(clrs), 100));	
		}
	}
	for (let i = 0; i < 20; i++) {
		const x = floor(random(-1, width/tileS + 1));
		const y = floor(random(-1, height/tileS + 1));
		const f = floor(random(1, 3));
		bars.push(new NeonBar(tileS * x, tileS * y, 0, tileS * f, random(clrs), 100));	
	}
	/*
	bars.push(new NeonBar(tileS * 2, tileS, 0, tileS * 2, random(clrs), 100));	
	bars.push(new NeonBar(tileS * 2, tileS * 2, 0, tileS * 2, random(clrs), 100));	
	bars.push(new NeonBar(tileS, tileS * 1.5, HALF_PI, tileS, random(clrs), 100));	
	bars.push(new NeonBar(tileS * 3, tileS * 1.5, HALF_PI, tileS, random(clrs), 100));	
	*/

	// duplicate existing to move
	numMove = bars.length;
	for (let i = 0; i < numMove; i++) {
		bars.push(bars[i].copy());
	}

	background("#091833");
}

function draw() {
	background(9,24,51, 64); // 0, 0, 12, 64);

	translate(width/2, height/2)
	rotate(frameCount * 0.00612)
	translate(-width/2, -height/2)

	for (let i = 0; i < bars.length; i++) {
	// for (let b of bars) {
		const b = bars[i];
		if (i < numMove) {
			b.update(0, tileS * tan(frameCount * 0.021), frameCount * -0.00612);
		} else {
			b.update(tileS * cos(frameCount * 0.0121), tileS * -sin(frameCount * 0.021), frameCount * 0.00312);
		}
		b.show();
	}

	// // noLoop() removed for animation
}

class NeonBar {
	constructor(x, y, a, l, clr, int, act = true) {
		this.x = x;
		this.y = y;
		this.a = a;
		this.l = l;
		this.clr = clr;
		this.int = int;
		this.act = act;
		this.n = 1;
		this.ox = 0;
		this.oy = 0;
		this.oa = 0;
	}

	update(ox = 0, oy = 0, oa = 0) {
		this.n = noise(this.x * 0.01 + frameCount * 0.021 + oa, this.y * 0.03 - oa);
		this.act = this.n < 0.65
		if (false && !this.act) {
			this.ox = 0;
			this.oy = 0;
			this.oa = 0;
			return;
		}
		this.ox = ox;
		this.oy = oy;
		this.oa = oa;
		// this.a = floor(4  * noise(this.x * 0.01 + frameCount * 0.021, this.y * 0.0273)) / 4 * TWO_PI + PI * 0.25;
		// this.act = noise(this.x * 0.01 + frameCount * 0.021, this.y * 0.03) < 0.45
		 this.clr = clrs[floor(clrs.length * (noise(this.x * 0.02 + frameCount * 0.0121, this.y * 0.023)))];
	}

	copy(ox = 0, oy = 0) {
		const n = new NeonBar(this.x + ox, this.y + oy, this.a, this.l, this.clr, this.int, this.act);
		return n;
	}

	show() {
		// only draw active bars
		// if (!this.act) return;

		push();
		noFill();
		noStroke();
		translate(this.x + this.ox, this.y + this.oy);
		rotate(this.a + this.oa); 
		rectMode(CENTER);

		let clr = color(red(window.color(this.clr)), green(window.color(this.clr)), blue(window.color(this.clr)), map(this.n, 0.25, 0.75, 0, 1) * 256);
		fill(clr);
		drawingContext.shadowColor = clr; // this.clr;
		drawingContext.shadowBlur = this.int;
		rect(0, 0, this.l, this.l); // 4

		drawingContext.shadowColor = color(255, this.n * 256); // "white";
		drawingContext.shadowBlur = this.int * 0.5;
		rect(0, 0, this.l, this.l);

		drawingContext.shadowColor = clr; // this.clr;
		drawingContext.shadowBlur = this.int * 0.25;
		rect(0, 0, this.l, this.l);

		pop();
	}
}
